update public.lessons
set content='{"intro": "Esta aula transforma «IMT e Imposto do Selo na aquisição» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "IMT e Imposto do Selo devem ser tratados com base no valor tributável, tipo de imóvel, finalidade, perfil do adquirente e regras em vigor na data do facto tributário. As tabelas podem mudar anualmente."}, {"title": "Como aplicar na prática", "body": "Recolher preço, VPT, finalidade, residência fiscal e demais dados relevantes; usar o simulador/legislação atual da Autoridade Tributária; documentar que o resultado é uma simulação."}, {"title": "O que confirmar antes de concluir", "body": "Em 2026 existem alterações relevantes nas taxas e regras, incluindo tratamento específico de determinadas aquisições habitacionais por não residentes. Não memorize tabelas como conteúdo permanente."}, {"title": "Exemplo profissional", "body": "Exemplo: duas compras pelo mesmo preço podem ter IMT diferente por finalidade ou enquadramento do comprador."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer os impostos e saber que informação é necessária para uma simulação, mas não deve transformar exemplos em aconselhamento fiscal individual. Taxas, isenções e enquadramentos devem ser confirmados na legislação vigente e, quando necessário, com contabilista ou fiscalista."}], "takeaway": "Competência concluída: saber tratar «IMT e Imposto do Selo na aquisição» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: duas compras pelo mesmo preço podem ter IMT diferente por finalidade ou enquadramento do comprador."}'::jsonb,
    source_url='https://info.portaldasfinancas.gov.pt/',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=170;
