update public.lessons
set content='{"intro": "Esta aula transforma «Identificação, beneficiário efetivo e origem de fundos» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "A atividade imobiliária está abrangida por deveres de prevenção do branqueamento e financiamento do terrorismo. O formando deve conhecer identificação, diligência, beneficiário efetivo, avaliação de risco, conservação de informação e procedimentos de comunicação/abstenção quando aplicáveis."}, {"title": "Como aplicar na prática", "body": "Seguir o procedimento interno: identificar e verificar cliente/representantes; compreender a estrutura de propriedade e beneficiário efetivo; recolher informação sobre finalidade e, quando exigível, origem/destino de fundos; reconhecer sinais de alerta; escalar internamente."}, {"title": "O que confirmar antes de concluir", "body": "Sinal de alerta não é acusação. O consultor não decide por intuição nem avisa o cliente de procedimentos confidenciais; segue a Lei n.º 83/2017 e o Regulamento IMPIC n.º 603/2021."}, {"title": "Exemplo profissional", "body": "Exemplo: estrutura societária opaca, pagamentos atípicos e resistência em explicar fundos justificam diligência reforçada e escalamento."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Identificação, beneficiário efetivo e origem de fundos» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: estrutura societária opaca, pagamentos atípicos e resistência em explicar fundos justificam diligência reforçada e escalamento."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232375',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=180;
update public.lessons
set content='{"intro": "Esta aula transforma «Sinais de alerta no negócio imobiliário» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O objetivo desta aula é dominar «Sinais de alerta no negócio imobiliário» no contexto de Prevenção do Branqueamento de Capitais — AML. O formando deve conseguir explicar o conceito, identificar a documentação ou informação necessária, reconhecer os principais riscos e saber qual é o próximo passo profissional."}, {"title": "Como aplicar na prática", "body": "Transforme «Sinais de alerta no negócio imobiliário» num procedimento: 1) definir o objetivo do cliente; 2) recolher fontes adequadas; 3) verificar atualidade e correspondência; 4) comparar com a realidade e outras fontes; 5) classificar divergências; 6) comunicar apenas conclusões suportadas; 7) encaminhar o que exigir competência especializada."}, {"title": "O que confirmar antes de concluir", "body": "Evite tratar «Sinais de alerta no negócio imobiliário» como uma formalidade. Pergunte sempre o que o dado/documento prova, o que não prova, se está atual e que efeito tem no negócio."}, {"title": "Exemplo profissional", "body": "Exemplo profissional: perante uma informação relacionada com «Sinais de alerta no negócio imobiliário» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Sinais de alerta no negócio imobiliário» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo profissional: perante uma informação relacionada com «Sinais de alerta no negócio imobiliário» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232375',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=181;
update public.lessons
set content='{"intro": "Esta aula transforma «Dados pessoais na mediação» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O RGPD exige finalidade, base de licitude, minimização, transparência, segurança e respeito pelos direitos dos titulares. Consentimento é apenas uma das possíveis bases legais e nem sempre é a adequada."}, {"title": "Como aplicar na prática", "body": "Antes de recolher/partilhar dados, definir finalidade e base; recolher apenas o necessário; informar o titular; controlar acessos; definir retenção; evitar documentos pessoais em canais inadequados."}, {"title": "O que confirmar antes de concluir", "body": "Um contacto comercial não autoriza qualquer utilização futura dos dados. Fotografias, documentos de identificação e dados financeiros exigem cuidado acrescido."}, {"title": "Exemplo profissional", "body": "Exemplo: enviar por WhatsApp um dossier completo com documentos pessoais a vários interessados sem necessidade é um risco de proteção de dados."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve cumprir os procedimentos internos e reconhecer situações que exigem escalamento. Não deve improvisar decisões de compliance nem divulgar informação protegida; dúvidas devem ser encaminhadas para o responsável competente."}], "takeaway": "Competência concluída: saber tratar «Dados pessoais na mediação» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: enviar por WhatsApp um dossier completo com documentos pessoais a vários interessados sem necessidade é um risco de proteção de dados."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/detalhe/lei/15-2013-257806',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=182;
